package com.example.demo.api;
import tools.jackson.databind.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.net.*;import java.net.http.*;import java.util.*;
@RestController @RequestMapping("/api/weather") public class WeatherController{
 private final ObjectMapper json=new ObjectMapper();
 @GetMapping public ResponseEntity<?> get(@RequestParam(defaultValue="29.987")double latitude,@RequestParam(defaultValue="31.211")double longitude){if(latitude < -90||latitude>90||longitude < -180||longitude>180)return ResponseEntity.badRequest().body(Map.of("error","Invalid coordinates"));try{String url="https://api.open-meteo.com/v1/forecast?latitude="+latitude+"&longitude="+longitude+"&current=temperature_2m,relative_humidity_2m,precipitation,weather_code&hourly=precipitation_probability&forecast_days=1";var req=java.net.http.HttpRequest.newBuilder(URI.create(url)).timeout(java.time.Duration.ofSeconds(6)).GET().build();var res=HttpClient.newHttpClient().send(req,HttpResponse.BodyHandlers.ofString());if(res.statusCode()!=200)return ResponseEntity.status(502).body(Map.of("error","Weather provider unavailable"));JsonNode root=json.readTree(res.body());JsonNode now=root.path("current");int rain=root.path("hourly").path("precipitation_probability").path(0).asInt(0);return ResponseEntity.ok(Map.of("available",true,"temperature",now.path("temperature_2m").asDouble(),"humidity",now.path("relative_humidity_2m").asInt(),"rainProbability",rain,"condition",condition(now.path("weather_code").asInt()),"location","Giza, Egypt","time",now.path("time").asText()));}catch(Exception e){return ResponseEntity.status(503).body(Map.of("available",false,"error","Weather information is temporarily unavailable"));}}
 private String condition(int c){if(c==0)return "Clear sky";if(c<=3)return "Partly cloudy";if(c==45||c==48)return "Foggy";if(c>=51&&c<=67)return "Drizzle or rain";if(c>=71&&c<=77)return "Snow";if(c>=80&&c<=82)return "Rain showers";if(c>=95)return "Thunderstorm";return "Cloudy";}
}


